<?php require_once __DIR__.'/../includes/init.php';require_roles(['super_admin','principal']);$page_title='User Accounts';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['name']);$email=trim($_POST['email']);$role=$_POST['role'];$pw=$_POST['password'];$roles=['principal','admin_officer','teacher','accountant','hr_officer'];if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<12||!in_array($role,$roles,true))$err='Check email, role and 12+ character password.';else{try{$q=$pdo->prepare('INSERT INTO users(full_name,email,password_hash,role) VALUES(?,?,?,?)');$q->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT),$role]);flash('User account created.');go('users/index.php');}catch(Throwable $e){$err='User not created. Email may already exist.';}}}
$rows=$pdo->query('SELECT full_name,email,role,is_active,created_at FROM users ORDER BY id DESC')->fetchAll();require __DIR__.'/../includes/header.php';?><h1>User Accounts</h1><?php if($err):?><div class="notice error"><?=h($err)?></div><?php endif;?><div class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="formgrid"><div><label>Name</label><input name="name" required></div><div><label>Email</label><input name="email" type="email" required></div><div><label>Role</label><select name="role"><?php foreach(['principal','admin_officer','teacher','accountant','hr_officer'] as $r):?><option><?=$r?></option><?php endforeach;?></select></div><div><label>Temporary password (12+ chars)</label><input name="password" type="password" minlength="12" required></div></div><button>Create user</button></form></div><div class="panel"><table><tr><th>Name</th><th>Email</th><th>Role</th><th>Active</th><th>Created</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['full_name'])?></td><td><?=h($r['email'])?></td><td><?=h($r['role'])?></td><td><?=h($r['is_active'])?></td><td><?=h($r['created_at'])?></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/../includes/footer.php';?>